#!/usr/bin/env bash
# Generates .env with random secrets for the lab (git-ignored).
set -euo pipefail
cd "$(dirname "$0")/.."
if [[ -f .env && "${1:-}" != "--force" ]]; then
  echo ".env already exists (use --force to regenerate)"; exit 0
fi
# AD password policy needs upper, lower, digit and symbol.
rnd() { printf '%s' "$(openssl rand -base64 18 | tr -dc 'A-Za-z0-9' | head -c 14)Aa1!"; }
cat > .env <<EOF
# Generated by scripts/gen-env.sh -- lab secrets, never commit
AD_ADMIN_PASSWORD=$(rnd)
AD_SVC_KEYCLOAK_PASSWORD=$(rnd)
AD_USER_PASSWORD=$(rnd)
KC_ADMIN_USER=kcadmin
KC_ADMIN_PASSWORD=$(rnd)
PORTAL_OIDC_CLIENT_SECRET=$(openssl rand -hex 24)
REPORTING_JOB_CLIENT_SECRET=$(openssl rand -hex 24)
FLASK_SECRET_OIDC=$(openssl rand -hex 32)
FLASK_SECRET_SAML=$(openssl rand -hex 32)
EOF
chmod 600 .env
echo ".env written"
